// Language support: English pages live at the site root, Thai copies in /th/ (generated by
// scripts/build-th.mjs from the English pages + i18n/th.json). Thai pages load
// assets/js/i18n-th.js first, which sets window.IB_TH (English text → Thai).
// Exposes window.IBI18n and the shorthand ibT(text, vars), e.g. ibT('Only {n} left', { n: 2 }).
(function () {
  var lang = document.documentElement.lang === "th" ? "th" : "en";
  var dict = lang === "th" ? (window.IB_TH || {}) : {};

  // Absolute URL of the site root, from this script's own address (…/assets/js/i18n.js),
  // so it is right on /, /th/ and /admin/ pages alike.
  var me = document.currentScript;
  var root = me && me.src ? new URL("../../", me.src).href : new URL(lang === "th" ? "../" : "./", location.href).href;

  // Translate a UI string. Unknown strings (and every string on English pages) come back
  // unchanged. {name} placeholders are filled from vars after translating.
  function t(text, vars) {
    var out = (lang === "th" && Object.prototype.hasOwnProperty.call(dict, text)) ? dict[text] : text;
    if (vars) out = out.replace(/\{(\w+)\}/g, function (m, k) { return k in vars ? vars[k] : m; });
    return out;
  }

  // The current page's address in the given language: /shop.html?x ↔ /th/shop.html?x.
  function urlFor(target) {
    var rootPath = new URL(root).pathname;
    var page = location.pathname.indexOf(rootPath) === 0 ? location.pathname.slice(rootPath.length) : "";
    page = page.replace(/^th(\/|$)/, "");
    return root + (target === "th" ? "th/" : "") + page + location.search + location.hash;
  }

  window.IBI18n = {
    lang: lang,
    t: t,
    root: root,                                   // e.g. https://infinite-box.co/
    asset: function (path) { return root + path; },  // asset("assets/img/x.png")
    urlFor: urlFor,
    locale: lang === "th" ? "th-TH" : undefined    // dates: th-TH shows the Buddhist year; EN keeps the browser's
  };
  window.ibT = t;
})();
